function normalizeSearch(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/front[\s-]*end/g,'frontend').replace(/\bdeveloper\b/g,'engineer').replace(/(?<!\w)c\+\+(?!\w)/g,' cplusplus ').replace(/(?<!\w)c#(?!\w)/g,' csharp ').replace(/[^a-z0-9]+/g,' ').replace(/\b(?:intern|interns|internship|internships|magang|praktikum)\b/g,'magang').replace(/\b(?:administrasi|administration)\b/g,'admin').trim();}
function emptyFilters(){return {countries:[],region:'',city:'',mode:'',eligible:'',sector:'',employment:'',level:'',sourceType:'',sourceName:'',recency:'',status:'active'};}
function normalizeLevel(value){const level=String(value||'').toLowerCase().replace(/[_-]/g,' ').replace(/\s+/g,' ').trim(),labels={pemula:'Pemula',entry:'Pemula','entry level':'Pemula',junior:'Junior',menengah:'Menengah',middle:'Menengah',mid:'Menengah','mid level':'Menengah',senior:'Senior'};return Object.hasOwn(labels,level)?labels[level]:'Belum diketahui';}
function normalizeFilters(filters={},items=catalog){
 const source=filters&&typeof filters==='object'?filters:{},f=emptyFilters();
 for(const key of Object.keys(f)){if(key==='countries')continue;if(typeof source[key]==='string')f[key]=source[key].slice(0,150);}
 f.countries=Array.isArray(source.countries)?[...new Set(source.countries.filter(value=>typeof value==='string').map(value=>value.slice(0,100)))].slice(0,20):[];
 if(f.level)f.level=normalizeLevel(f.level);
 if(!['active','all','open','unknown','closed','expired'].includes(f.status))f.status='active';
 if(f.countries.length!==1){f.region='';f.city='';}
 if(f.region&&!items.some(j=>j.country===f.countries[0]&&j.region===f.region)){f.region='';f.city='';}
 if(f.city&&!items.some(j=>j.country===f.countries[0]&&(!f.region||j.region===f.region)&&j.city===f.city))f.city='';
 return f;
}
function effectiveJobStatus(job){
 const dateOnly=typeof job.deadline==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(job.deadline),deadline=dateOnly?job.deadline+'T23:59:59.999Z':job.deadline,time=Date.parse(deadline);
 if(!job.mock&&job.status!=='closed'&&Number.isFinite(time)&&time<Date.now())return 'expired';
 return job.status;
}
function filterCatalog(items,query,filters=emptyFilters()){
 const terms=normalizeSearch(query).split(' ').filter(Boolean),f={...emptyFilters(),...filters};
 return items.filter(j=>{
  const status=effectiveJobStatus(j),haystack=normalizeSearch([j.title,j.company,j.sector,j.employment,...j.skills,...(!j.mock?[j.description||'']:[])].join(' ')),words=haystack.split(' '),nativeMatch=!!j.searchQuery&&normalizeSearch(j.searchQuery)===normalizeSearch(query);
  return terms.every(term=>['c','cplusplus','csharp'].includes(term)?words.includes(term):nativeMatch||haystack.includes(term))&&(!f.countries.length||(!j.mock&&Array.isArray(j.countries)&&j.countries.length?j.countries:[j.country]).some(country=>f.countries.includes(country)))&&(!f.region||j.region===f.region)&&(!f.city||j.city===f.city)&&(!f.mode||j.mode===f.mode)&&(!f.eligible||j.eligible.includes(f.eligible)||j.eligible.includes('Global'))&&(!f.sector||j.sector===f.sector)&&(!f.employment||j.employment===f.employment)&&(!f.level||normalizeLevel(j.level)===normalizeLevel(f.level))&&(!f.sourceType||j.sourceType===f.sourceType)&&(!f.sourceName||j.sourceName===f.sourceName)&&(!f.recency||(Number.isFinite(j.postedDays)&&j.postedDays<=Number(f.recency)))&&(f.status==='all'||f.status==='active'&&!['closed','expired'].includes(status)||status===f.status);
 });
}
function parseProfileText(text){
 const profile=emptyProfile(),labels={nama:'fullName',name:'fullName',email:'email',jabatan:'role',posisi:'role',role:'role',lokasi:'location',location:'location',keahlian:'skills',skills:'skills',pengalaman:'experience',experience:'experience',pendidikan:'education',education:'education',bahasa:'languages',languages:'languages'};
 let current='';
 for(const line of String(text).slice(0,250000).split(/\r?\n/)){
  const match=line.match(/^\s*([A-Za-z ]+)\s*:\s*(.*)$/);
  if(match){current=labels[match[1].trim().toLowerCase()]||'';if(current)profile[current]=match[2].trim();}
  else if(current&&line.trim())profile[current]+='\n'+line.trim();
 }
 return profile;
}
function safeHttpURL(value){try{const url=new URL(String(value).trim());return ['http:','https:'].includes(url.protocol)&&!url.username&&!url.password?url.href:'';}catch{return '';}}
