 if(options.responseType==='blob'&&response.ok){if(response.headers.get('Content-Type')?.split(';')[0]!=='application/pdf')throw new Error('Layanan lokal belum menghasilkan PDF yang valid. Coba unduh kembali.');return response.blob();}
