function render(focus=false){page=Object.hasOwn(pages,location.hash.slice(1))?location.hash.slice(1):'beranda';document.getElementById('main-content').innerHTML=(storageIssue?`<div class="notice">${ico('info')}<span>${esc(storageIssue)}</span></div>`:'')+demoNote()+runBox()+viewFns[page]();document.title='SuperWork — '+pages[page][0];document.getElementById('breadcrumb-page').textContent=pages[page][0];document.getElementById('profile-nav-count').textContent=state.confirmed?'✓':state.cv?'Tinjau':'CV';document.getElementById('apps-nav-count').textContent=state.apps.length;document.getElementById('side-model-name').textContent=modelName();document.getElementById('side-user-name').textContent=state.profile.fullName?state.profile.fullName+(isExampleProfile()?' · Contoh':''):'Profil kandidat';document.getElementById('job-nav-count').textContent=searchableJobs().length;document.querySelectorAll('[data-page]').forEach(link=>{const active=link.dataset.page===page;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});document.querySelector('.notification-dot').hidden=!state.interviews.length;hydrateIcons();updateConnectionUI();setSaveStatus(storageIssue?'Belum tersimpan':savedSequence<saveSequence?'Menyimpan…':'Tersimpan lokal');closeSidebar();if(focus)document.querySelector('main h1')?.focus({preventScroll:true});}
